insert into public.academy_course_structures
    (app_slug, tier, structure, content_version)
insert into public.academy_quiz_questions
    (app_slug, tier, scope, module_key, ord, prompt, options, answer_index, explanation)
values
  ('carbon', 'advanced', 'module', 'm01-the-cost-of-a-tonne-abated', 1, 'On the invented AGBOR records, the capital box of one measure is left empty (the Heat integration project). What is the engine''s answer?', '["A refusal asking for a life to annualise the capital cost over.", "A refusal asking for a discount rate, since a blank is not read as 0.", "A refusal telling the user to enter 0 if the measure needs no capital.", "A cost per tonne of -120.5882 USD, with capital cost named in assumedZero."]'::jsonb, 2, 'SECTION 19 prints, for the capital cost blank: REFUSED: Measure "Heat integration project" has no capital cost. Enter 0 if it needs none: a blank is not read as free. The life and rate refusals belong to other blanks, and assumedZero names only the running figures.'),
  ('carbon', 'advanced', 'module', 'm01-the-cost-of-a-tonne-abated', 2, 'The invented Heat integration project is sent with its annual savings and its annual cost both left blank. What does abatementCost return?', '["costPerTonne 106.3391 USD, with assumedZero naming annual savings and annual cost", "costPerTonne -14.2492 USD, the same figure as with the savings entered", "costPerTonne -120.5882 USD, with assumedZero naming annual savings only", "A refusal asking for the annual savings before any cost is computed"]'::jsonb, 0, 'SECTION 19: blank running figures are taken as 0 and NAMED; with the savings and the running cost blank the measure answers costPerTonne 106.3391 USD, assumedZero: annual savings, annual cost. -14.2492 USD is the measure as costed in SECTION 18, and -120.5882 USD is the call with capital 0 typed.'),
  ('carbon', 'advanced', 'module', 'm01-the-cost-of-a-tonne-abated', 3, 'A user types the discount rate as 10, meaning ten percent, on a measure with capital. What does abatementCost do?', '["It accepts it and annualises the capital exactly as a rate of 0.1 would, at ten percent.", "It refuses: a measure with capital needs a rate, and a blank is not read as 0.", "It accepts it and prints the Heat integration project at -14.2492 USD a tonne.", "It refuses: the rate is a fraction above -1 and below 1, typed 0.1 for ten percent."]'::jsonb, 3, 'SECTION 19, discount rate 10 (a percentage typed): REFUSED: The discount rate is a fraction greater than -1 and below 1 (0.1 for ten percent). The blank-rate refusal is a different call, and -14.2492 USD a tonne is the measure costed at a rate of 0.1.'),
  ('carbon', 'advanced', 'module', 'm01-the-cost-of-a-tonne-abated', 4, 'The invented Heat integration project is sent with a capital of 0 typed, and no life and no rate. What comes back?', '["A refusal asking for a life to annualise the capital over", "costPerTonne -120.5882 USD and capitalRecoveryFactor 0.00000000", "A refusal asking for a discount rate to annualise the capital", "costPerTonne 106.3391 USD, with capital cost named in assumedZero"]'::jsonb, 1, 'SECTION 19: a capital of 0 typed needs no life and no rate: Heat integration project with capital 0 answers costPerTonne -120.5882 USD and capitalRecoveryFactor 0.00000000. 106.3391 USD is the call with the savings and the running cost blank.'),
  ('carbon', 'advanced', 'module', 'm01-the-cost-of-a-tonne-abated', 5, 'A measure is sent with an abatement of 0 tonnes a year. What does abatementCost return?', '["A refusal saying the measure needs an annual abatement.", "costPerTonne none, and paysForItself false.", "A refusal saying the measure has a negative abatement.", "costPerTonne none, and paysForItself true."]'::jsonb, 1, 'SECTION 19: an abatement of 0 is accepted and has no cost per tonne: costPerTonne none, paysForItself false. The annual abatement refusal is the call with the abatement blank, and the negative abatement refusal is the call with -500 t a year.'),
  ('carbon', 'advanced', 'module', 'm01-the-cost-of-a-tonne-abated', 6, 'The invented Agbor measures are costed at a rate of 0 (straight line) as well as at 0.1. Which measure''s cost per tonne carries a minus sign at one rate and none at the other?', '["Flare gas recovery, 78.1002 at 0.1 and 26.8817 at 0", "Vapour recovery on the storage tanks, 35.4193 at 0.1 and 14.5045 at 0", "Heat integration project, -14.2492 at 0.1 and -66.6667 at 0", "Solar for purchased power, 45.8573 at 0.1 and -13.5714 at 0"]'::jsonb, 3, 'SECTION 18 prints Solar for purchased power at 45.8573 USD a tonne at 0.1 and -13.5714 USD a tonne at a rate of 0. The other three rows keep one sign at both rates: Flare gas recovery and Vapour recovery stay positive, and the Heat integration project stays negative.'),
  ('carbon', 'advanced', 'module', 'm01-the-cost-of-a-tonne-abated', 7, 'The invented Heat integration project and Flare gas recovery both print a capital recovery factor of 0.13147378. What do the two rows share that the factor is built from?', '["A life of 15 years, at the same discount rate of 0.1.", "A capital cost of 2750000 USD, annualised the same way.", "The heaters as their source, so one factor serves both.", "An annual cost of 0 USD, so nothing is added to capital."]'::jsonb, 0, 'SECTION 18 prints the factor as r(1 + r)^n / ((1 + r)^n - 1): the rate and the life. Both rows carry a life of 15 years at 0.1. Their capital costs are 2750000 and 4900000 USD, they act on heaters and flare, and Flare gas recovery carries an annual cost of 105000 USD.'),
  ('carbon', 'advanced', 'module', 'm01-the-cost-of-a-tonne-abated', 8, 'For the invented Heat integration project, which figure sits in the SECTION 18 column whose header is marked computed here?', '["-14.2492 USD a tonne, the cost per tonne at the rate of 0.1", "-66.6667 USD a tonne, the cost per tonne at a rate of 0", "688.2353 USD a tonne, the whole capital set against one year", "-120.5882 USD a tonne, the cost with a capital of 0 typed"]'::jsonb, 2, 'Of the two columns in SECTION 18''s second table, only the header of the capital-against-one-year column carries (computed here), and the sentence above it says the engine refuses to compare a one-off cost with a recurring saving. -14.2492 USD is the cost per tonne at 0.1, -66.6667 USD the cost per tonne at a rate of 0, and -120.5882 USD the answer with capital 0 typed (SECTION 19).'),
  ('carbon', 'advanced', 'module', 'm01-the-cost-of-a-tonne-abated', 9, 'A capital measure arrives with its life box empty. Apart from asking for the life, which sentence does the refusal carry?', '["A blank life is read as one year, so the whole capital lands in a single year''s saving.", "A blank life would annualise straight-line and move the measure down the curve.", "A blank life is not read as free, so 0 must be entered if the measure has none.", "Set against one year''s saving, a one-off capital cost overstates the cost per tonne."]'::jsonb, 3, 'SECTION 19, life blank, second sentence: "Set against one year''s saving, a one-off capital cost overstates the cost per tonne of a capital measure." The engine refuses the call; it never reads a blank life as one year.'),
  ('carbon', 'advanced', 'module', 'm01-the-cost-of-a-tonne-abated', 10, 'The six invented Agbor measures are handed to the curve with the Heat integration project''s capital cost blank. What does the curve return?', '["6 steps and totalAbatementTonnes 15460.000, the measure placed at a capital of 0", "5 steps and totalAbatementTonnes 12060.000, with the measure named in refusedMeasures", "No curve at all: the whole call is refused until the capital cost is entered", "5 steps and totalAbatementTonnes 15460.000, the refused measure''s tonnes still in it"]'::jsonb, 1, 'SECTION 19: 5 steps, totalAbatementTonnes 12060.000, and refusedMeasures lists Heat integration project with its capital refusal. The refusedNote: "A refused measure is off the curve and out of every total until it is costed." 15460.000 is the curve with all six costed (SECTION 20).'),
  ('carbon', 'advanced', 'module', 'm01-the-cost-of-a-tonne-abated', 11, 'The invented Tune the fired heaters prints a net annual cost of -127251.65 USD. How does SECTION 18 define the net annual cost?', '["The annualised capital plus the annual cost less the annual savings.", "The whole capital, undivided, plus the annual cost less the annual savings.", "The annual savings less the annualised capital and the annual cost together.", "The cost per tonne multiplied by the capital recovery factor and the tonnes."]'::jsonb, 0, 'SECTION 18: the net annual cost is the annualised capital plus the annual cost less the annual savings; the cost per tonne is that over the tonnes abated a year. For Tune the fired heaters that is 4748.35 USD of annualised capital, an annual cost of 0 and savings of 132000 USD.'),
  ('carbon', 'advanced', 'module', 'm01-the-cost-of-a-tonne-abated', 12, 'Costed at the invented discount rate of 0.1, which of these Agbor measures reads pays for itself true?', '["Vapour recovery on the storage tanks", "Solar for purchased power", "Heat integration project", "Flare gas recovery"]'::jsonb, 2, 'SECTION 18 prints the Heat integration project at -14.2492 USD a tonne, pays for itself true: a negative cost per tonne means the measure pays for itself and abates carbon as a side effect. Vapour recovery (35.4193), Solar (45.8573) and Flare gas recovery (78.1002) read false.'),
  ('carbon', 'advanced', 'module', 'm01-the-cost-of-a-tonne-abated', 13, 'A measure with capital is sent with its discount rate blank. What does the refusal say reading that blank as 0 would do?', '["Overstate the cost per tonne of a capital measure set against one year.", "Set the whole capital against one year of the measure''s savings.", "Annualise straight-line and move the measure down the curve.", "Read the capital cost as free, as a blank capital cost would be."]'::jsonb, 2, 'SECTION 19, discount rate blank: "A blank is not read as 0, which would annualise straight-line and move the measure down the curve." Overstating is the wording of the life blank, and free is the wording of the capital blank.'),
  ('carbon', 'advanced', 'module', 'm01-the-cost-of-a-tonne-abated', 14, 'Which pair of invented Agbor measures prints a minus sign both at the rate of 0.1 and in the capital-against-one-year column?', '["Tune the fired heaters and the Heat integration project", "Repair failed steam traps and Solar for purchased power", "Heat integration project and Vapour recovery on the storage tanks", "Tune the fired heaters and Repair failed steam traps"]'::jsonb, 3, 'SECTION 18: Tune the fired heaters prints -167.4364 and -150.0000 USD a tonne, and Repair failed steam traps -156.4390 and -133.0435. The Heat integration project prints 688.2353 against one year, Solar 45.8573 at 0.1 and Vapour recovery 35.4193 at 0.1.'),
  ('carbon', 'advanced', 'module', 'm01-the-cost-of-a-tonne-abated', 15, 'The invented Flare gas recovery prints a net annual cost of 484221.51 USD. Which three printed figures does SECTION 18''s definition build it from?', '["Annualised capital 644221.51, annual cost 105000 and savings 265000 USD", "Capital 4900000, annual cost 105000 and annual savings 265000 USD", "Annualised capital 644221.51, annual cost 105000 and 6200 tonnes", "Annualised capital 361552.89, annual cost 105000 and savings 265000 USD"]'::jsonb, 0, 'SECTION 18 defines the net annual cost as the annualised capital plus the annual cost less the annual savings. Flare gas recovery''s row prints annualised capital 644221.51 USD, annual cost 105000 USD and annual savings 265000 USD. 361552.89 USD is the Heat integration project''s annualised capital, and the tonnes are the divisor of the cost per tonne.'),
  ('carbon', 'advanced', 'module', 'm02-the-marginal-abatement-cost-curve', 1, 'On the curve built from the six invented AGBOR measures, which measure is order 2?', '["Tune the fired heaters, at -167.4364 USD a tonne", "Repair failed steam traps, at -156.4390 USD a tonne", "Solar for purchased power, at 45.8573 USD a tonne", "Heat integration project, at -14.2492 USD a tonne, with its 3400.000 t"]'::jsonb, 1, 'SECTION 20''s second row is Repair failed steam traps, costed at -156.4390 USD a tonne; the first row is Tune the fired heaters, and Solar sits fifth.'),
  ('carbon', 'advanced', 'module', 'm02-the-marginal-abatement-cost-curve', 2, 'What sets a measure''s order on the Agbor curve?', '["Its tonnes a year, largest first", "The order it was entered in SECTION 18''s table", "Its capital cost, the smallest capital first", "Its cost per tonne, cheapest first"]'::jsonb, 3, 'SECTION 20: the six measures ranked cheapest first. Flare gas recovery has the largest tonnes, 6200.000, and is order 6. Vapour recovery on the storage tanks is entered sixth and is order 4. The Heat integration project, with 2750000 USD of capital, is order 3 ahead of Vapour recovery at 610000 USD.'),
  ('carbon', 'advanced', 'module', 'm02-the-marginal-abatement-cost-curve', 3, 'Where does the invented Heat integration project''s step start and end on the Agbor curve''s axis?', '["From 1910.000 t to 5310.000 t", "From 760.000 t to 1910.000 t, after the heaters", "From 5310.000 t to 7160.000 t, as order 4", "From 0.000 t to 3400.000 t, as the first step"]'::jsonb, 0, 'SECTION 20 prints the Heat integration project, order 3, with cumulative start 1910.000 t and cumulative end 5310.000 t; its width is its 3400.000 t a year. 760.000 to 1910.000 is Repair failed steam traps and 5310.000 to 7160.000 is Vapour recovery on the storage tanks.'),
  ('carbon', 'advanced', 'module', 'm02-the-marginal-abatement-cost-curve', 4, 'The Agbor curve prints weightedAverageCostPerTonne 18.7868 USD. How does SECTION 20 define that figure?', '["The mean of the six costs per tonne, each counted once", "netAnnualCostOfAll over paysForItselfTonnes, 5310.000 t", "netAnnualCostOfAll over totalAbatementTonnes", "The middle step''s cost per tonne"]'::jsonb, 2, 'SECTION 20: the weighted average is the net annual cost of all the measures over the total tonnes, 290443.84 USD over 15460.000 t. The mean of the six costs per tonne, each counted once, is -29.7913 USD (computed here).'),
  ('carbon', 'advanced', 'module', 'm02-the-marginal-abatement-cost-curve', 5, 'SECTION 20 computes a plain mean of the six Agbor costs per tonne, -29.7913 USD. What does the digest say that plain mean does?', '["It counts the heater measures twice, as they share a source.", "It leaves the three measures that pay for themselves out of it.", "It weights a small measure the same as a large one.", "It sums the net annual costs to four decimals before dividing."]'::jsonb, 2, 'SECTION 20: the plain mean of the six costs per tonne (computed here) is -29.7913 USD, which weights a small measure the same as a large one. The four-decimal sum belongs to the rounding note on netAnnualCostOfAll, and the plain mean takes in all six costs.'),
  ('carbon', 'advanced', 'module', 'm02-the-marginal-abatement-cost-curve', 6, 'The six net annual costs as SECTION 18 prints them sum to 290443.85 USD, while the curve prints netAnnualCostOfAll 290443.84 USD. What does the rounding note say the engine does?', '["It sums the net annual costs it holds to four decimals.", "It drops one cent for the measure that is refused.", "It removes the heater overlap before it sums the costs.", "It rounds each cost per tonne before weighting the six."]'::jsonb, 0, 'SECTION 20''s ROUNDING NOTE: the six net annual costs as printed in SECTION 18 sum to 290443.85 USD; the engine sums the net annual costs it holds to four decimals, which gives 290443.84 USD. No measure is refused on this curve, and the overlap is surfaced as additive false.'),
  ('carbon', 'advanced', 'module', 'm02-the-marginal-abatement-cost-curve', 7, 'The Agbor curve prints paysForItselfTonnes 5310.000. Which figure on the step table carries the same value?', '["The cumulative end of order 2, Repair failed steam traps, 1910.000 t", "The tonnes a year of the Heat integration project, 3400.000 t", "The cumulative start of order 6, Flare gas recovery, 9260.000 t", "The cumulative end of order 3, the Heat integration project"]'::jsonb, 3, 'SECTION 20 prints order 3, the Heat integration project, with cumulative end 5310.000 t, and paysForItselfTonnes 5310.000 with paysForItselfMeasures naming orders 1 to 3. The other options carry 1910.000, 3400.000 and 9260.000 t.'),
  ('carbon', 'advanced', 'module', 'm02-the-marginal-abatement-cost-curve', 8, 'The Agbor curve prints additive false. Which entry in SECTION 20 goes with that flag?', '["An over-claims entry naming the flare: Flare gas recovery claiming more than it emits", "An interaction table naming heaters: Tune the fired heaters and the Heat integration project", "A refusedMeasures entry naming the Heat integration project, whose capital was blank", "A paysForItselfMeasures entry naming Tune the fired heaters and Repair failed steam traps"]'::jsonb, 1, 'SECTION 20 prints the interaction table, heaters: Tune the fired heaters; Heat integration project, with the note that measures acting on the same source are NOT additive. The costed curve carries no refused measure, over-claims belong to the 9400 t claim of SECTION 21, and paysForItselfMeasures names three measures.'),
  ('carbon', 'advanced', 'module', 'm02-the-marginal-abatement-cost-curve', 9, 'Which of these does SECTION 26 list as recomputed by neither oracle?', '["paysForItselfTonnes on the curve", "the curve''s rank order", "each measure''s levelised cost per tonne", "the path''s year-by-year abated tonnes"]'::jsonb, 0, 'SECTION 26 lists paysForItselfTonnes as recomputed by neither oracle. oracle_carbonabatement.py takes the curve by explicit rank, each cost per tonne from a present value ledger and the path as a year ledger.'),
  ('carbon', 'advanced', 'module', 'm02-the-marginal-abatement-cost-curve', 10, 'SECTION 20 prints 0.343467 beside the Agbor curve''s outputs. What is it?', '["Flare gas recovery''s share of the axis, returned by the engine with the curve", "The weighted average cost per tonne over the plain mean, computed by the digest", "The capital recovery factor of the Heat integration project at a rate of 0.1", "paysForItselfTonnes as a share of totalAbatementTonnes, computed by the digest"]'::jsonb, 3, 'SECTION 20: paysForItselfTonnes as a share of totalAbatementTonnes (computed here), 0.343467. The Heat integration project''s capital recovery factor is 0.13147378 (SECTION 18), and the digest prints no share for Flare gas recovery and no ratio of the two averages.'),
  ('carbon', 'advanced', 'module', 'm02-the-marginal-abatement-cost-curve', 11, 'The invented Flare gas recovery abates 6200.000 t a year. Which order does the Agbor curve give it, and where does its step start?', '["Order 1, starting at 0.000 t", "Order 4, starting at 5310.000 t", "Order 6, starting at 9260.000 t", "Order 6, starting at 7160.000 t"]'::jsonb, 2, 'SECTION 20 prints Flare gas recovery as order 6 at 78.1002 USD a tonne, cumulative start 9260.000 t and end 15460.000 t. 7160.000 t is where order 5, Solar for purchased power, starts, and 5310.000 t is the start of order 4.'),
  ('carbon', 'advanced', 'module', 'm02-the-marginal-abatement-cost-curve', 12, 'On the Agbor step chart, what does the height of a step show?', '["The measure''s tonnes abated a year", "The measure''s cost per tonne in US dollars", "The measure''s capital cost in US dollars", "The measure''s cumulative end on the axis"]'::jsonb, 1, 'SECTION 20: each step''s width is its tonnes a year and its height its cost per tonne; the steps tile the axis from 0. The cumulative end is where a step stops along the width axis.'),
  ('carbon', 'advanced', 'module', 'm02-the-marginal-abatement-cost-curve', 13, 'Which pair gives the Agbor curve''s weighted average and the digest''s plain mean, in that order?', '["-29.7913 and 18.7868 USD a tonne", "18.7868 USD a tonne and 0.343467", "290443.84 USD and -29.7913 USD a tonne", "18.7868 and -29.7913 USD a tonne"]'::jsonb, 3, '18.7868 USD is the engine''s weightedAverageCostPerTonne; -29.7913 USD is the digest''s own plain mean, computed here. 290443.84 USD is a money total and 0.343467 a share of tonnes.'),
  ('carbon', 'advanced', 'module', 'm02-the-marginal-abatement-cost-curve', 14, 'Where does the first step of the Agbor curve start, and which measure is it?', '["At 0.000 t, Tune the fired heaters", "At 0.000 t, Repair failed steam traps", "At 760.000 t, Tune the fired heaters", "At 0.000 t, Flare gas recovery"]'::jsonb, 0, 'SECTION 20: the steps tile the axis from 0, and order 1 is Tune the fired heaters, cumulative start 0.000 and end 760.000 t, at -167.4364 USD a tonne. Repair failed steam traps is order 2 from 760.000 t, and Flare gas recovery is order 6.'),
  ('carbon', 'advanced', 'module', 'm02-the-marginal-abatement-cost-curve', 15, 'Which two measures sit either side of zero on the Agbor curve, as orders 3 and 4?', '["Repair failed steam traps at -156.4390 and Heat integration project at -14.2492", "Heat integration project at -14.2492 and Vapour recovery on the storage tanks at 35.4193", "Heat integration project at -14.2492 and Solar for purchased power at 45.8573", "Vapour recovery on the storage tanks at 35.4193 and Solar for purchased power at 45.8573"]'::jsonb, 1, 'Read SECTION 20''s order column: 3 is the Heat integration project, the last negative step, and 4 is Vapour recovery on the storage tanks, the first positive one.'),
  ('carbon', 'advanced', 'module', 'm03-interactions-and-over-claims', 1, 'On the invented AGBOR inventory (IPCC AR6 GWP100, fossil methane), which emission does the Carbon Studio pass to the curve for the flare?', '["6189.848 tCO2e, the Flaring (CO2) line alone", "1372.285 tCO2e, the unburned CH4 line alone", "7562.133 tCO2e, its CO2 plus its methane in CO2e", "9400.000 t, the claim of Flare gas recovery on it"]'::jsonb, 2, 'SECTION 21: each source''s emission is its CO2 plus its methane in CO2e, as the Carbon Studio passes it to the curve; the flare source is passed as 7562.133 tCO2e. 6189.848 and 1372.285 tCO2e are its two inventory lines, and 9400 t is the enlarged claim of the second curve.'),
  ('carbon', 'advanced', 'module', 'm03-interactions-and-over-claims', 2, 'Flare gas recovery''s invented claim is raised to 9400 t a year with the flare''s emission passed. What does the over-claims column print?', '["flare: claimed 9400.000 against 7562.133 emitted", "flare: claimed 9400.000 against 6189.848 emitted", "flare: claimed 6200.000 against 7562.133 emitted", "none, since the flare''s emission was passed to the curve"]'::jsonb, 0, 'SECTION 21, the curve with flare gas recovery claiming 9400 t: over-claims flare: claimed 9400.000 against 7562.133 emitted. 6189.848 tCO2e is the flare''s CO2 line alone, and at its costed 6200 t the first curve prints over-claims none.'),
  ('carbon', 'advanced', 'module', 'm03-interactions-and-over-claims', 3, 'Which targetBasis does SECTION 21 print on the curve where Flare gas recovery claims 9400 t with the flare''s emission passed?', '["not assessed: no computed emission to check the claims on steam, power, vents", "not assessed: no computed emission to check the claims on steam, flare, power, vents", "not assessed: no computed emission to check the claims on steam", "not assessed: claims exceed what a source emits"]'::jsonb, 3, 'SECTION 21 prints "not assessed: claims exceed what a source emits" on that row. The steam, power, vents basis is the six measures as costed, the basis naming the flare is the same claim with the flare''s emission not passed, and the steam-only basis is the curve with every computed source passed.'),
  ('carbon', 'advanced', 'module', 'm03-interactions-and-over-claims', 4, 'Rerun that 9400 t curve, this time giving it no flare emission. What do the over-claims column and the targetBasis print?', '["flare: claimed 9400.000 against 7562.133 emitted, found as on the row before", "none, and the targetBasis names the flare among the sources it could not check", "flare: claimed 9400.000 against 0.000 emitted, since no emission was passed", "none, and the targetBasis reads claims exceed what a source emits"]'::jsonb, 1, 'SECTION 21, the same claim with the flare''s emission not passed: over-claims none, meetsTarget none, targetBasis "not assessed: no computed emission to check the claims on steam, flare, power, vents". With nothing passed for the flare there is nothing to check the claim against.'),
  ('carbon', 'advanced', 'module', 'm03-interactions-and-over-claims', 5, 'On the six invented Agbor measures as costed, which measures does the engine list among the unchecked claims?', '["Repair failed steam traps, Solar for purchased power and Vapour recovery on the storage tanks", "Tune the fired heaters, Solar for purchased power and Vapour recovery on the storage tanks", "Repair failed steam traps, Flare gas recovery and Vapour recovery on the storage tanks", "Repair failed steam traps, Solar for purchased power and the Heat integration project"]'::jsonb, 0, 'SECTION 21 lists the unchecked claims of the first row: Repair failed steam traps (steam), Solar for purchased power (power) and Vapour recovery on the storage tanks (vents), each with the reason no emission was given for the source. Heaters and flare are the two sources passed.'),
  ('carbon', 'advanced', 'module', 'm03-interactions-and-over-claims', 6, 'Every source the Agbor inventory computes is passed to the curve. Which source does uncheckedSources still name?', '["power, the Purchased electricity line on Scope 2", "vents, the vented and fugitive methane line", "steam, which has no line of its own in the Agbor inventory", "flare, as its emission is passed as its CO2 line alone"]'::jsonb, 2, 'SECTION 21: with every source the inventory computes passed, uncheckedSources is steam: the Agbor inventory has no line of its own for steam. Power (10988.000 tCO2e) and vents (2622.400 tCO2e) join heaters and flare, and the flare is passed as its CO2 plus its methane.'),
  ('carbon', 'advanced', 'module', 'm03-interactions-and-over-claims', 7, 'SECTION 21 costs Flare gas recovery at its 9400 t claim. Against the costed 6200 t, what moves?', '["The net annual cost falls to 290443.84 USD and the cost per tonne holds", "The net annual cost stays at 484221.51 USD and the cost per tonne rises", "Both hold, at 484221.51 USD and 78.1002 USD a tonne, since no cost moves", "The net annual cost stays at 484221.51 USD and the cost per tonne falls"]'::jsonb, 3, 'SECTION 21 costs the 9400 t claim at a net annual cost of 484221.51 USD, the figure SECTION 18 prints for the measure at 6200 t and 78.1002 USD a tonne, and reads it: "The cost per tonne falls as the claimed tonnes rise; the over-claim makes the measure look cheaper as well as larger." 290443.84 USD is the curve''s netAnnualCostOfAll.'),
  ('carbon', 'advanced', 'module', 'm03-interactions-and-over-claims', 8, 'SECTION 21 closes with its rules for a target verdict. In which case does the verdict stand, labelled an upper bound?', '["Where a claim exceeds what its source emits.", "Where measures only interact and every claim is checked.", "Where a claim acts on a source whose emission is not passed.", "Where every source the inventory computes is passed to it."]'::jsonb, 1, 'SECTION 21: "Where measures only interact and every claim is checked, the verdict stands and is labelled an upper bound." A claim above its source''s emission gives none, a claim on a source not passed gives none, and the curve with every computed source passed still prints none, on steam.'),
  ('carbon', 'advanced', 'module', 'm03-interactions-and-over-claims', 9, 'Tune the fired heaters and the Heat integration project both act on heaters. What does the engine do with their tonnes on the curve?', '["It keeps the larger claim, 3400.000 t, and drops Tune the fired heaters from the total.", "It refuses the curve until the user sequences the two measures on the one source.", "It counts both in full, 760.000 and 3400.000 t, and calls the cumulative curve an upper bound.", "It counts both in full and names heaters in the over-claims column of the curve."]'::jsonb, 2, 'SECTION 20 prints both measures at 760.000 and 3400.000 t, additive false, and the note: "Measures listed here act on the same source, so their abatements are NOT additive and the cumulative curve is an upper bound. Resolving the overlap needs an engineering judgement about sequencing, which is why it is surfaced rather than solved." The costed curve prints over-claims none.'),
  ('carbon', 'advanced', 'module', 'm03-interactions-and-over-claims', 10, 'Every SECTION 21 curve is checked against a target of 16830.083 tCO2e. What is that target?', '["30 percent of the inventory total of 56100.276 tCO2e", "30 percent of the curve''s total abatement of 15460.000 t", "The purchased electricity line of 10988.000 tCO2e", "The path''s target in its end year, 39270.193 t"]'::jsonb, 0, 'SECTION 21: the target is 30 percent of the inventory total: 16830.083 tCO2e (computed here, as the Carbon Studio computes it). The inventory total is 56100.276 tCO2e. 39270.193 t is the path''s target in 2033 (SECTION 22).'),
  ('carbon', 'advanced', 'module', 'm03-interactions-and-over-claims', 11, 'The six measures as costed print a residual to target of 1370.083 t beside meetsTarget none. How does SECTION 26 treat the curve''s residual?', '["Recomputed by oracle_carbonabatement.py as part of its year ledger", "Recomputed by oracle_energyefficiency.py as a levelised cost per tonne", "Recomputed by both oracles, and its goldens asserted by the test suites", "Recomputed by neither oracle; taught from the engine and never graded"]'::jsonb, 3, 'The residual is on SECTION 26''s list of outputs no oracle recomputes, so it is taught from the engine and never graded. A year ledger is the oracle''s route for the path, a different output.'),
  ('carbon', 'advanced', 'module', 'm03-interactions-and-over-claims', 12, 'With every source the inventory computes passed, which two sources join heaters and flare, and at what emissions?', '["steam 10988.000 and vents 2622.400 tCO2e", "power 10988.000 and vents 2622.400 tCO2e", "power 10988.000 and steam 2622.400 tCO2e", "power 1372.285 and vents 2622.400 tCO2e"]'::jsonb, 1, 'SECTION 21, the sources added with every computed source passed: power 10988.000 tCO2e and vents 2622.400 tCO2e, from the Purchased electricity and the Vented and fugitive methane lines. Steam has no inventory line, and 1372.285 tCO2e is the flare''s unburned CH4 line.'),
  ('carbon', 'advanced', 'module', 'm03-interactions-and-over-claims', 13, 'Flare gas recovery''s invented claim is raised from 6200 t to 9400 t. Which curve figure moves, and to what?', '["Total abatement, from 15460.000 to 18660.000 t", "The target, from 16830.083 to 18660.000 t", "The residual to target, from 0.000 to 1370.083 t", "The flare''s emission passed, from 7562.133 to 9400.000"]'::jsonb, 0, 'SECTION 21 prints total abatement 15460.000 t on the six as costed and 18660.000 t with the 9400 t claim. The target is 16830.083 t on both rows, the residual moves from 1370.083 to 0.000 t, and the flare''s emission passed stays 7562.133 tCO2e.'),
  ('carbon', 'advanced', 'module', 'm03-interactions-and-over-claims', 14, 'Of the curves SECTION 21 prints, which returns a verdict on the target?', '["The six measures as costed, labelled an upper bound.", "The curve with every source the inventory computes.", "None of them: every row prints meetsTarget none.", "The 9400 t claim, whose total passes the target."]'::jsonb, 2, 'SECTION 21 prints meetsTarget none on all four rows, each with a targetBasis beginning "not assessed": three on sources with no computed emission, one on claims that exceed what a source emits.'),
  ('carbon', 'advanced', 'module', 'm03-interactions-and-over-claims', 15, 'On the six measures as costed, what reason does the engine give for Solar for purchased power''s unchecked claim?', '["claims exceed what a source emits on power", "measures act on the same source as solar", "the power line could not be computed", "no emission was given for the source"]'::jsonb, 3, 'SECTION 21''s unchecked claims of the first row: Solar for purchased power, power, no emission was given for the source. The over-claim wording belongs to the 9400 t row, and the shared-source wording to SECTION 20''s interaction note on heaters.'),
  ('carbon', 'advanced', 'module', 'm04-targets-and-the-path', 1, 'On the invented AGBOR path, which year is firstShortfallYear, and what gap does the path print in it?', '["2028, with a gap of 798.595 t", "2027, with a gap of 494.298 t", "2033, the end year, with a gap of 1370.083 t", "2029, when the Heat integration project starts"]'::jsonb, 1, 'SECTION 22: firstShortfallYear: 2027, and the 2027 row prints an unabated gap of 494.298 t. 2028 prints 798.595 t, 2033 prints 1370.083 t, and 2029 prints 0.000.'),
  ('carbon', 'advanced', 'module', 'm04-targets-and-the-path', 2, 'The Agbor electricity factor is left blank and the path is built on that inventory. What does it print for finalGapTonnes?', '["1370.083 t, the same final gap the path prints on the full inventory", "3220.083 t, with purchased electricity named as unscheduled", "0.000 t, on a baseline of 45112.276 tCO2e that is reportable false", "A refusal: the baseline must be a positive tonnage"]'::jsonb, 2, 'SECTION 22, ON A PARTIAL INVENTORY: with the electricity factor blank the inventory totals 45112.276 tCO2e and is reportable false; the path on it prints finalGapTonnes 0.000. 1370.083 t is the full inventory''s final gap and 3220.083 t the path with a measure unscheduled.'),
  ('carbon', 'advanced', 'module', 'm04-targets-and-the-path', 3, 'Built on the partial Agbor inventory instead of the full one, which path figure moves from 39270.193 t to 31578.593 t?', '["The target in the end year", "finalGapTonnes, the gap in 2033", "The emissions the path prints in 2033", "The tonnes abated in the end year"]'::jsonb, 0, 'SECTION 22 prints the target in the end year as 39270.193 t on the full inventory and 31578.593 t on the partial one. finalGapTonnes moves from 1370.083 to 0.000, and the measures are the same six.'),
  ('carbon', 'advanced', 'module', 'm04-targets-and-the-path', 4, 'How does decarbonisationPath report the Agbor gap of 1370.083 t in the end year?', '["As a wedge of future measures that closes it by 2033", "As a cost, at the curve''s weighted average of 18.7868 USD a tonne", "As a refusal until a measure is named to close it", "As unabated, with no measure identified"]'::jsonb, 3, 'SECTION 22, the gap note: "The gap is reported as unabated with no measure identified. It is deliberately not drawn as a wedge of future measures, because a wedge with nothing behind it is not a plan." The path prints finalGapTonnes 1370.083 and no refusal.'),
  ('carbon', 'advanced', 'module', 'm04-targets-and-the-path', 5, 'In 2029 the Agbor path prints emissions of 48690.276 t against a target of 48887.383 t. What does the unabated gap column print?', '["494.298 t, carried on from 2027", "798.595 t, carried on from 2028", "815.785 t, the gap before 2033", "0.000 t, by the rule in every row"]'::jsonb, 3, 'SECTION 22: in every row the unabated gap is emissions less the target where that is positive, else 0.000. The 2029 row prints 0.000. Each row is read on its own emissions and target: 494.298 t is the 2027 row and 798.595 t the 2028 row, and 815.785 t is the 2032 row of the unscheduled path.'),
  ('carbon', 'advanced', 'module', 'm04-targets-and-the-path', 6, 'Vapour recovery on the storage tanks is given no start year. What does the path do with it?', '["Starts it in 2026, the baseline year, so finalGapTonnes stays 1370.083", "Names it in unscheduledMeasures and leaves it off; finalGapTonnes 3220.083", "Refuses the whole path until a start year is entered for the measure", "Starts it in 2033, the end year, and prints finalGapTonnes 1850.000"]'::jsonb, 1, 'SECTION 22: a measure with no start year is named and left off the path: unscheduledMeasures Vapour recovery on the storage tanks (no start year); finalGapTonnes 3220.083. SECTION 25 lists the rule: a measure with no start year is named.'),
  ('carbon', 'advanced', 'module', 'm04-targets-and-the-path', 7, 'The digest prints the unscheduled path''s final gap less the scheduled one as 1850.000 t. Which figure does SECTION 22 say that matches?', '["The tonnes a year of the measure left unscheduled", "The gap the unscheduled path prints in 2032", "The full baseline less the partial baseline", "Repair failed steam traps'' tonnes a year"]'::jsonb, 0, 'SECTION 22: that gap less the scheduled plan''s 1370.083 is 1850.000 t (computed here), the vapour recovery measure''s tonnes a year. The unscheduled 2032 gap is 815.785 t, the full baseline less the partial is 10988.000 tCO2e, and Repair failed steam traps abates 1150.000 t.'),
  ('carbon', 'advanced', 'module', 'm04-targets-and-the-path', 8, 'The same six Agbor measures are run against an invented baseline of 12000 t. What comes back?', '["A path whose emissions reach 0.000 t in 2030 and stay", "A path with finalGapTonnes 0.000 and no shortfall year", "A refusal naming 2030, when the measures abate 13610 t", "A refusal naming 2031, when the measures abate 15460.000 t"]'::jsonb, 2, 'SECTION 22: REFUSED: In 2030 the scheduled measures abate 13610 t against a baseline of 12000 t. Emissions cannot fall below zero, so check the measures for double counting or a source outside the baseline. overAbatedYear 2030.'),
  ('carbon', 'advanced', 'module', 'm04-targets-and-the-path', 9, 'An inventory that computed nothing is handed to decarbonisationPath as a baseline of 0. What does the engine say?', '["It refuses: the baseline must be a positive tonnage.", "It draws the path from 0 and prints every gap as 0.000.", "It builds the path on the partial total of 45112.276 tCO2e.", "It names the inventory in unscheduledMeasures and goes on."]'::jsonb, 0, 'SECTION 22: REFUSED: The baseline must be a positive tonnage. An inventory that computed nothing is not a baseline of zero. SECTION 25 lists it: a baseline that is not positive is refused. 45112.276 tCO2e is the partial inventory with the electricity factor blank.'),
  ('carbon', 'advanced', 'module', 'm04-targets-and-the-path', 10, 'Which invented Agbor measure joins the path in 2028?', '["Heat integration project", "Vapour recovery on the storage tanks", "Flare gas recovery", "Solar for purchased power"]'::jsonb, 3, 'The start-year table gives Solar for purchased power 2028, and the 2028 row adds it to the two measures live since 2027. The other three start in 2029, 2030 and 2031.'),
  ('carbon', 'advanced', 'module', 'm04-targets-and-the-path', 11, 'Which invented Agbor measure is the last to go live on the path?', '["Flare gas recovery, in 2030, as order 6", "Vapour recovery on the storage tanks, in 2031", "Solar for purchased power, in 2028", "Heat integration project, in 2029, as order 3"]'::jsonb, 1, 'SECTION 22''s start years run from 2027 to 2031, and Vapour recovery on the storage tanks carries 2031; its row joins the measures live from 2031. Flare gas recovery starts in 2030, Solar for purchased power in 2028 and the Heat integration project in 2029.'),
  ('carbon', 'advanced', 'module', 'm04-targets-and-the-path', 12, 'How does the Carbon Studio draw the target on the Agbor path?', '["In steps, falling each time one of the measures goes live", "Flat at 16830.083 t, which is 30 percent of the Agbor inventory total", "In a straight line from 56100.276 t in 2026 to 39270.193 t in 2033", "In a straight line from 56100.276 t in 2026 to 16830.083 t in 2033"]'::jsonb, 2, 'SECTION 22: the target falls in a straight line from the baseline in 2026 to 30 percent below it in 2033, as the Carbon Studio draws it: 56100.276 t in 2026 and 39270.193 t in 2033. 16830.083 tCO2e is the curve''s target of SECTION 21, and each measure counts in full from its start year.'),
  ('carbon', 'advanced', 'module', 'm04-targets-and-the-path', 13, 'From 2031 to 2033 the Agbor target falls from 44078.788 to 39270.193 t. Which column holds one value across those years?', '["Unabated gap, at 0.000 t", "Abated tonnes, at 13610.000 t", "Unabated gap, at 1370.083 t in each", "Emissions, at 40640.276 t"]'::jsonb, 3, 'SECTION 22 prints emissions of 40640.276 t and abated tonnes of 15460.000 t in 2031, 2032 and 2033. The gap prints 0.000 in 2031 and 2032 and 1370.083 t in 2033, and 13610.000 t is the abated column of the unscheduled path.'),
  ('carbon', 'advanced', 'module', 'm04-targets-and-the-path', 14, 'One path summary figure agrees between the partial inventory and the full one. Which?', '["firstShortfallYear, 2027", "finalGapTonnes, 1370.083", "The end-year target, 39270.193", "The baseline, 56100.276 tCO2e"]'::jsonb, 0, 'SECTION 22 prints firstShortfallYear 2027 on both baselines. On the partial inventory the end-year target is 31578.593 t, finalGapTonnes 0.000 and the baseline 45112.276 tCO2e.'),
  ('carbon', 'advanced', 'module', 'm04-targets-and-the-path', 15, 'Take the unscheduled variant of the path. Which 2032 row does SECTION 22 print for it?', '["0.000 t of gap on 15460.000 t abated", "3220.083 t of gap on 13610.000 t abated", "815.785 t of gap on 13610.000 t abated", "815.785 t of gap on 15460.000 t abated"]'::jsonb, 2, 'SECTION 22, the path with the measure unscheduled: 2032, abated 13610.000 t, emissions 42490.276 t, target 41674.491 t, gap 815.785 t. 3220.083 t is its 2033 gap, and 15460.000 t is the scheduled path''s abated column.'),
  ('carbon', 'advanced', 'module', 'm05-savings-into-the-ledger', 1, 'The invented AGBOR saving is priced with no emission factor supplied. What does priceSaving return for the carbon?', '["annualTonnesCo2e 0.000, with the money value returned beside it as usual", "A refusal saying an emission factor is required before any pricing", "annualTonnesCo2e 661.980, read from a factor the engine ships", "annualTonnesCo2e none, with a note that the carbon figure is absent"]'::jsonb, 3, 'SECTION 23, no emission factor: annualTonnesCo2e none; carbonNote "No emission factor supplied, so the carbon figure is absent rather than zero." SECTION 25: emission factors are inputs and neither engine ships one. 661.980 is the carbon with the SYNTHETIC factor of 56.1 kg CO2e per GJ.'),
  ('carbon', 'advanced', 'module', 'm05-savings-into-the-ledger', 2, 'The invented saving is declared on LHV and its emission factor on HHV. What does priceSaving do?', '["It computes and attaches the basisNote asking for all three on the same basis.", "It refuses: a gigajoule on one basis is a different amount of fuel on the other.", "It converts the factor to LHV and returns 661.980 tCO2e with basis LHV.", "It computes and returns basis HHV beside the money and the carbon."]'::jsonb, 1, 'SECTION 23: REFUSED: The energy saving is on LHV, the emission factor is on HHV. A gigajoule on one heating value basis is a different amount of fuel on the other, so they cannot be multiplied together. The basisNote is the answer when no basis is declared at all.'),
  ('carbon', 'advanced', 'module', 'm05-savings-into-the-ledger', 3, 'The invented saving is sent with no heating value basis declared. What does priceSaving do?', '["It returns a basisNote: the saving, price and factor must share one basis", "It refuses: the energy saving is on LHV and the emission factor on HHV", "It reads every quantity as LHV by default and returns basis LHV with no note", "It refuses: an energy saving and a basis are both required to price"]'::jsonb, 0, 'SECTION 23, no basis declared: basisNote "No heating value basis declared. The saving, the fuel price and the emission factor must all be on the same one (IPCC default factors are on net calorific value, which is LHV)." That row prints no refusal. The LHV and HHV refusal is the call with the saving on LHV and the factor on HHV, and the only saving refusal printed is for a blank saving.'),
  ('carbon', 'advanced', 'module', 'm05-savings-into-the-ledger', 4, 'The invented saving is priced with no life and no rate. What comes back for the cost per tonne?', '["A refusal, the one abatementCost gives a measure with capital and no life", "costPerTonneCo2e 183.5403 USD, the whole cost set against one year", "costPerTonneCo2e none, with a note asking for the life and a discount rate", "costPerTonneCo2e -74.2270 USD, annualised straight line at a rate of 0"]'::jsonb, 2, 'SECTION 23, no life and no rate: costPerTonneCo2e none; costPerTonneNote "A cost per tonne needs the measure life and a discount rate, to annualise the implementation cost against a yearly saving." -74.2270 USD is the cost at 8 years and 0.1, and 183.5403 USD is the digest''s one-year figure.'),
  ('carbon', 'advanced', 'module', 'm05-savings-into-the-ledger', 5, 'The invented saving prints simplePaybackYears 2.372881. What does SECTION 23 say that figure is?', '["210000 over 88500.00, discounted at 0.1 over the 8 year life", "210000 over 88500.00: undiscounted, with no life and no rate in it", "39363.24 over 88500.00, the annualised cost over one year''s value", "210000 over 661.980, the implementation cost over a year''s tonnes"]'::jsonb, 1, 'SECTION 23: the simple payback is the implementation cost over one year''s value, 210000 / 88500.00 = 2.372881 years (computed here): undiscounted, with no life and no rate in it. 39363.24 USD is the annualised capital of the direct abatementCost call.'),
  ('carbon', 'advanced', 'module', 'm05-savings-into-the-ledger', 6, 'priceSaving hands the invented saving to abatementCost. Which argument does the implementation cost of 210000 USD fill?', '["The annual cost", "The annual savings", "The tonnes abated a year", "The capital"]'::jsonb, 3, 'SECTION 23: the cost per tonne is carbonAbatement.abatementCost called with the implementation cost as capital, the annual value as the saving and the annual tonnes as the abatement. The annual cost is not one of the three arguments SECTION 23 names.'),
  ('carbon', 'advanced', 'module', 'm05-savings-into-the-ledger', 7, 'The same invented saving is sent to abatementCost directly, over 8 years at a rate of 0.1. Which net annual cost does it print?', '["netAnnualCost -49136.76 USD", "netAnnualCost 39363.24 USD", "netAnnualCost 88500.00 USD", "netAnnualCost -127251.65 USD, on the curve''s first step"]'::jsonb, 0, 'SECTION 23, the same call made directly: capitalRecoveryFactor 0.18744402, annualisedCapital 39363.24 USD, netAnnualCost -49136.76 USD, costPerTonne -74.2270 USD, paysForItself true. -127251.65 USD is Tune the fired heaters'' net annual cost in SECTION 18.'),
  ('carbon', 'advanced', 'module', 'm05-savings-into-the-ledger', 8, 'Setting the whole implementation cost against one year''s value and one year''s tonnes gives which figure, and what is its status?', '["183.5403 USD a tonne, the engine''s costPerTonneCo2e output", "-74.2270 USD a tonne, which SECTION 23 labels (computed here)", "183.5403 USD a tonne, which SECTION 23 labels (computed here)", "2.372881 years, the engine''s simplePaybackYears for the saving"]'::jsonb, 2, 'SECTION 23: "Setting the whole implementation cost against one year''s value and one year''s tonnes (computed here) gives 183.5403 USD a tonne." The engine''s costPerTonneCo2e is -74.2270 USD, from abatementCost over 8 years at 0.1, and 2.372881 years is simplePaybackYears.'),
  ('carbon', 'advanced', 'module', 'm05-savings-into-the-ledger', 9, 'SECTION 26 names what no oracle recomputes. Which of these is on that list?', '["The levelised cost per tonne of the saving, -74.2270 USD", "The excess air, which the oracle solves by bisection", "The steam trap flow, taken as an isentropic nozzle", "The simple payback, 2.372881 years"]'::jsonb, 3, 'SECTION 26 puts the simple payback on its not-recomputed list. The energyEfficiency oracle does compute a levelised cost per tonne, excess air by bisection and the trap as an isentropic nozzle.'),
  ('carbon', 'advanced', 'module', 'm05-savings-into-the-ledger', 10, 'With Purchased power blank, what does energyIntensity return beside an intensity of 629.8387 MJ a tonne?', '["complete false, with versus peer none and gap none", "complete false, versus peer 1.040085 and gap 27.2581", "A refusal: every stream is needed", "complete true, with 781000.000 GJ read as the whole plant"]'::jsonb, 0, 'SECTION 24, purchased power blank: complete false, total 781000.000 GJ, intensity 629.8387 MJ per tonne, versus peer none, gap none. 1.040085 and 27.2581 belong to the row with all three streams, and the only energyIntensity refusal printed is a throughput required.'),
  ('carbon', 'advanced', 'module', 'm05-savings-into-the-ledger', 11, 'What does the peerNote say an intensity with a stream missing is?', '["A ceiling, which would penalise the plant", "A floor, which would flatter the plant", "An upper bound on the streams", "Not reportable, as a line could not be computed"]'::jsonb, 1, 'SECTION 24, peerNote with a stream missing, verbatim: "Not compared with the peer: a stream is missing, so the intensity is a floor and would flatter the plant." SECTION 25 lists the rule: an intensity with a stream missing is not compared with the peer.'),
  ('carbon', 'advanced', 'module', 'm05-savings-into-the-ledger', 12, 'Agbor''s invented intensity is 707.2581 MJ a tonne against an invented peer of 680 MJ a tonne. What are versus peer and the gap?', '["0.843786, and a gap of 27.2581 MJ a tonne", "1.040085, and a gap of 629.8387 MJ a tonne", "1.040085, and a gap of 27.2581 MJ a tonne", "27.2581, and a gap of 1.040085 MJ a tonne"]'::jsonb, 2, 'SECTION 24: versus peer is the intensity over the peer, 1.040085; the gap is the intensity less the peer, 27.2581 MJ a tonne (each computed here and equal to the engine''s figure). 0.843786 is the Fuel gas share and 629.8387 MJ a tonne the intensity with Purchased power blank.'),
  ('carbon', 'advanced', 'module', 'm05-savings-into-the-ledger', 13, 'What does the energyIntensity disclaimer say the Agbor figure is?', '["The plant''s own energy per tonne of throughput", "The Solomon Energy Intensity Index for the plant", "The plant''s energy on a standard-energy basis", "A published peer benchmark supplied by the engine"]'::jsonb, 0, 'SECTION 24, the disclaimer: "This is the plant''s own energy per tonne of throughput. It is NOT the Solomon Energy Intensity Index, which is a proprietary benchmark with its own standard-energy methodology. Any peer figure compared here is one you supplied and have the right to use."'),
  ('carbon', 'advanced', 'module', 'm05-savings-into-the-ledger', 14, 'Which priceSaving call on the invented saving is refused outright?', '["No emission factor supplied", "No heating value basis declared", "No life and no rate given", "The saving left blank"]'::jsonb, 3, 'SECTION 23: REFUSED: An energy saving is required. No factor returns annualTonnesCo2e none with a carbonNote, no basis returns a basisNote, and no life and no rate returns costPerTonneCo2e none with a costPerTonneNote.'),
  ('carbon', 'advanced', 'module', 'm05-savings-into-the-ledger', 15, 'Of Agbor''s three invented energy streams, which one carries the share 0.109464?', '["Imported steam, 41000.000 GJ", "Fuel gas, 740000.000 GJ", "Purchased power, 96000.000 GJ", "Purchased power, 41000.000 GJ"]'::jsonb, 2, 'SECTION 24 prints Purchased power at 96000.000 GJ and a share of 0.109464, Fuel gas at 740000.000 GJ and 0.843786, and Imported steam at 41000.000 GJ and 0.046750, of 877000.000 GJ.'),
  ('carbon', 'advanced', 'module', 'm06-the-expert-reading', 1, 'Which of these does SECTION 25 hold as a stated limit under H1?', '["Which IPCC report a Nigerian operator files on is the owner''s decision.", "The engine ships the AR6 set as its default when no GWP is supplied.", "The course''s set is the one a Nigerian operator is to file its inventory on.", "The AR5 values are retired from the digest and no longer printed beside it."]'::jsonb, 0, 'H1 is held: the report is a regulatory reading left to the owner. No GWP ships with the engine, and both reports are printed side by side for the course.'),
  ('carbon', 'advanced', 'module', 'm06-the-expert-reading', 2, 'SECTION 26 names two oracles in the engines repository. Where are their goldens asserted?', '["By the course''s capstone grader", "By the digest''s computed-here lines", "By the engine test suites", "By the Carbon Studio each time it runs"]'::jsonb, 2, 'SECTION 26: two independent oracles in tools/validation/downstream recompute these modules by other routes, and their goldens are asserted by the engine test suites.'),
  ('carbon', 'advanced', 'module', 'm06-the-expert-reading', 3, 'What does held item H3 state?', '["Every escaped carbon atom is counted as CO2 at combustion.", "Every escaped carbon atom is counted as methane.", "Escaped carbon is left out of the inventory.", "Escaped carbon is split by the fuel analysis."]'::jsonb, 1, 'SECTION 25, H3: every escaped carbon atom is counted as methane (SECTION 5). It is a held item, taught as a stated limit and never graded.'),
  ('carbon', 'advanced', 'module', 'm06-the-expert-reading', 4, 'SECTION 25 lists each rule in force with the section that prints it. Which rule does it place in SECTION 21?', '["A refused measure is named in refusedMeasures and kept off the curve and its totals", "A year whose scheduled measures abate more than the baseline is refused by the path", "A saving, its price and its factor declared on different bases are refused outright", "A curve with a claim above what its source emits returns meetsTarget none and says why"]'::jsonb, 3, 'SECTION 25 places the over-claim rule, and the rule that a verdict is none while a claim acts on a source with no computed emission passed, in SECTION 21. The refusedMeasures rule prints in SECTION 19, the over-abatement refusal in SECTION 22 and the basis refusal in SECTION 23.'),
  ('carbon', 'advanced', 'module', 'm06-the-expert-reading', 5, 'The curve prints additive false for the two heater measures. How does the path count them once they are live?', '["Only the larger one", "Neither, until sequenced", "Each in full, from its own start year", "Each at its tonnes less the other''s claim"]'::jsonb, 2, 'SECTION 22: each measure counts in full from its start year. Tune the fired heaters counts from 2027 and the Heat integration project from 2029, and by 2031 the abated column reads 15460.000 t, the curve''s total.'),
  ('carbon', 'advanced', 'module', 'm06-the-expert-reading', 6, 'By which route does oracle_carbonabatement.py recompute a measure''s cost per tonne?', '["Levelised from a year-by-year present value ledger", "By the capital recovery factor the engine itself uses", "By explicit rank, the route it takes for the curve", "As a species ledger whose mass balance must close"]'::jsonb, 0, 'SECTION 26: the cost per tonne LEVELISED from a year-by-year present value ledger where the engine uses a capital recovery factor; the curve by explicit rank. The species ledger is oracle_energyefficiency.py''s combustion route.'),
  ('carbon', 'advanced', 'module', 'm06-the-expert-reading', 7, 'Solar for purchased power is order 5 on the Agbor curve. In which year does it go live on the path?', '["2030, a year after the Heat integration project", "2027, with Tune the fired heaters and the steam traps", "2031, the last start year among the six measures", "2028, a year before the Heat integration project"]'::jsonb, 3, 'Start years are inputs. SECTION 22 gives Solar for purchased power 2028 and the Heat integration project, order 3 on the curve of SECTION 20, 2029; the path goes by those years.'),
  ('carbon', 'advanced', 'module', 'm06-the-expert-reading', 8, 'How does oracle_energyefficiency.py model the steam trap?', '["By the choked and subsonic flux formulas that the engine itself uses for the trap", "As an isentropic nozzle, its throat at the larger of the downstream and critical pressures", "As a duty ledger, the route the oracle takes for the tuning saving", "By bisection on the downstream pressure, the route it takes for excess air"]'::jsonb, 1, 'SECTION 26: the steam trap as an ISENTROPIC NOZZLE with its throat at the larger of the downstream and critical pressures, where the engine uses the choked and subsonic flux formulas. The duty ledger is the tuning saving''s route and bisection is the excess air route.'),
  ('carbon', 'advanced', 'module', 'm06-the-expert-reading', 9, 'What are H1 to H4 in this course?', '["Rules in force, each shown with a figure", "Figures to compute with at the owner''s rates", "Limits, taught as stated and never graded", "Rules in force, each with its section"]'::jsonb, 2, 'SECTION 25: HELD, taught as stated limits and never graded. The rules in force are printed in tables of their own, each as the engine answers now with the section that prints it, and H1 to H4 are not among them.'),
  ('carbon', 'advanced', 'module', 'm06-the-expert-reading', 10, 'Which figure is both the Agbor curve''s totalAbatementTonnes and the path''s abated tonnes in 2031?', '["13610.000 t", "15460.000 t", "12060.000 t", "7410.000 t"]'::jsonb, 1, 'SECTION 20 prints totalAbatementTonnes 15460.000, and SECTION 22''s 2031 row prints 15460.000 t abated with all six measures live. 13610.000 t is the 2030 row, 12060.000 t the curve with one measure refused, and 7410.000 t the 2029 row.'),
  ('carbon', 'advanced', 'module', 'm06-the-expert-reading', 11, 'Two outputs of the Agbor curve are on SECTION 26''s list of what neither oracle recomputes. Which two?', '["The rank order and the costs per tonne it ranks", "The residual to target and paysForItselfTonnes", "The residual to target and the path''s year ledger", "The weighted average and the explicit rank order"]'::jsonb, 1, 'Both curve outputs sit on SECTION 26''s closing list beside carbonIntensity, compositeCurve and the simple payback: taught from the engine and never graded. Rank order has an oracle route of its own.'),
  ('carbon', 'advanced', 'module', 'm06-the-expert-reading', 12, 'How does oracle_carbonabatement.py compute combustion?', '["As a ledger, the route it takes for the inventory", "As a species ledger whose mass balance closes", "By bisection on the stack oxygen reading", "By mass, in exact rationals"]'::jsonb, 3, 'SECTION 26: combustion by MASS in exact rationals (kg of carbon times the CO2/C and CH4/C mass ratios, molar masses built from atomic weights). The ledger is its route for the inventory, the species ledger is oracle_energyefficiency.py''s combustion route, and bisection is that oracle''s route for excess air.'),
  ('carbon', 'advanced', 'module', 'm06-the-expert-reading', 13, 'The engine finds the pinch from a cascade. Which route does the efficiency oracle take to it?', '["By the problem table cascade the engine uses", "As a loss ledger, the route for efficiency", "By the largest heat deficit, with no cascade", "By bisection, the route it takes for excess air"]'::jsonb, 2, 'SECTION 26: the pinch by the LARGEST HEAT DEFICIT with no cascade. The loss ledger is the efficiency route and bisection the excess air route; SECTION 25 lists the engine''s rule that only an interior zero of the cascade is a pinch.'),
  ('carbon', 'advanced', 'module', 'm06-the-expert-reading', 14, 'SECTION 22 prints the full Agbor baseline less the partial one as 10988.000 tCO2e. What does it say that figure is?', '["The heaters'' emission passed to the curve", "The vented and fugitive methane line", "The gap between the two end-year targets", "The purchased electricity line of SECTION 21"]'::jsonb, 3, 'SECTION 22: the full baseline less the partial is 10988.000 tCO2e (computed here), the purchased electricity line of SECTION 21: the partial inventory is the full one without it. The heaters are passed as 34927.743 tCO2e and the vented line is 2622.400 tCO2e.'),
  ('carbon', 'advanced', 'module', 'm06-the-expert-reading', 15, 'Flare gas recovery goes live on the Agbor path in 2030. What emissions and target does the path print that year?', '["42490.276 t emitted, against a target of 46483.086 t", "48690.276 t emitted, against a target of 48887.383 t", "42490.276 t emitted, against a target of 41674.491 t", "40640.276 t emitted, against a target of 44078.788 t"]'::jsonb, 0, 'In the 2030 row, emissions are the baseline less 13610.000 t abated, 42490.276 t, and the straight-line target stands at 46483.086 t. 48690.276 and 48887.383 t are the 2029 row, 41674.491 t the 2032 target and 40640.276 t the emissions from 2031.'),
  ('carbon', 'advanced', 'final', null, 1, 'Which invented AGBOR measure carries the capital recovery factor 0.40211480 at the rate of 0.1?', '["Tune the fired heaters, over 5 years", "Vapour recovery on the storage tanks, over 12 years", "Repair failed steam traps, over 3 years", "Solar for purchased power, 20 years"]'::jsonb, 2, 'Keyed from the factor column of SECTION 18: 0.40211480 sits on the 3 year row. Five years gives 0.26379748, twelve 0.14676332 and twenty 0.11745962.'),
  ('carbon', 'advanced', 'final', null, 2, 'Which net annual cost and cost per tonne does SECTION 18 print for Solar for purchased power at 0.1?', '["96300.31 net, 45.8573 per tonne", "217300.31 net, 45.8573 per tonne", "96300.31 net, -13.5714 per tonne", "65525.62 net, 35.4193 per tonne"]'::jsonb, 0, 'Solar''s row: net 96300.31, per tonne 45.8573, both in USD. Its annualised capital is 217300.31; -13.5714 is its straight-line figure; 65525.62 with 35.4193 is the vapour recovery row.'),
  ('carbon', 'advanced', 'final', null, 3, 'Vapour recovery on the storage tanks appears in SECTION 18 at 35.4193, 14.5045 and 316.7568 USD a tonne. Which figure does the curve rank it by?', '["14.5045, straight line at a rate of 0", "316.7568, its capital against one year", "-29.7913, the plain mean of the curve", "35.4193, levelised at the rate of 0.1"]'::jsonb, 3, 'SECTION 20 ranks the measures cheapest first and prints order 4 at 35.4193, the cost per tonne at 0.1 in SECTION 18. 14.5045 is the rate-0 column, 316.7568 the capital-against-one-year column marked computed here, and -29.7913 the plain mean (computed here).'),
  ('carbon', 'advanced', 'final', null, 4, 'What does the curve''s refusedNote say of a measure abatementCost refused?', '["It is placed last on the curve at a cost per tonne of 0 USD.", "It is off the curve and out of every total until it is costed.", "It stays in totalAbatementTonnes and leaves the weighted average.", "It is costed at a capital of 0 and named in the assumedZero field."]'::jsonb, 1, 'SECTION 19, the refusedNote verbatim: "A refused measure is off the curve and out of every total until it is costed." assumedZero names blank running figures only, and a refused measure is not placed on the curve at any cost.'),
  ('carbon', 'advanced', 'final', null, 5, 'An invented abatement of -500 t a year is sent for the Heat integration project. Which reasons does the refusal give?', '["A measure that adds emissions is no abatement, and its cost per tonne would change sign.", "A blank abatement is not read as 0, which would move the measure down the curve.", "An abatement of -500 t exceeds what the heaters emit, so the claim is an over-claim.", "A negative abatement is read as 0, and the field is named in the assumedZero list."]'::jsonb, 0, 'SECTION 19 gives two grounds: adding emissions is no abatement, and the sign of the per-tonne figure would flip. Over-claims are a curve check in SECTION 21, and assumedZero covers only running figures.'),
  ('carbon', 'advanced', 'final', null, 6, 'Which step on the Agbor curve runs from 7160.000 t to 9260.000 t?', '["The fourth step, 1850.000 t a year wide", "The sixth step, 6200.000 t a year wide", "The fifth step, 2100.000 t a year wide", "The third step, 3400.000 t a year wide"]'::jsonb, 2, 'Order 5 starts where order 4 stops, at 7160.000, and stops at 9260.000; its width is Solar''s 2100.000 t a year.'),
  ('carbon', 'advanced', 'final', null, 7, 'The Agbor curve''s summary cost per tonne and the digest''s plain mean carry opposite signs. Which one does the engine return?', '["The plain mean, -29.7913 USD", "weightedAverageCostPerTonne, 18.7868 USD", "netAnnualCostOfAll, 18.7868 USD", "The plain mean, 18.7868 USD a tonne"]'::jsonb, 1, 'Only the weighted figure is an engine output. The unweighted -29.7913 is marked computed here, and netAnnualCostOfAll is a money total of 290443.84 USD.'),
  ('carbon', 'advanced', 'final', null, 8, 'Suppose every claim on a curve were checked and the only issue were two measures on one source. What does SECTION 21 say of the verdict?', '["It is none, as the claims are not additive.", "It is none, and the basis names the source.", "It is refused until the overlap is sequenced.", "It stands, and is labelled an upper bound."]'::jsonb, 3, 'Interaction alone, with every claim checked, leaves a standing verdict carrying the upper-bound label. A none belongs to over-claims and to claims on sources with no emission passed.'),
  ('carbon', 'advanced', 'final', null, 9, 'The 9400 t claim is run with the flare''s emission not passed. Which sources does its targetBasis name?', '["steam, power, vents", "flare", "steam", "steam, flare, power, vents"]'::jsonb, 3, 'With the flare''s emission left out, the flare joins the sources the basis names, four in all. Three are named on the six as costed, and one, steam, once every computed source is passed.'),
  ('carbon', 'advanced', 'final', null, 10, 'In the digest''s own words, what does raising a claim beyond its source''s emission do to how a measure looks?', '["It makes the measure look cheaper as well as larger.", "It leaves the cost per tonne at 78.1002 USD a tonne.", "It raises the net annual cost to match the new tonnes.", "It refuses the measure until the claim is brought down."]'::jsonb, 0, 'The reading attached to the 9400 t costing: the per-tonne figure falls as tonnes rise, a cheaper as well as larger look, with 484221.51 USD of net annual cost unchanged.'),
  ('carbon', 'advanced', 'final', null, 11, 'What emission does the Carbon Studio pass to the curve for the heaters source?', '["56100.276 tCO2e, the whole inventory total", "7562.133 tCO2e, the flare source", "34927.743 tCO2e, the fired heaters'' CO2 line", "10988.000 tCO2e, the purchased electricity line"]'::jsonb, 2, 'Heaters go to the curve as 34927.743, one inventory line. The flare goes as 7562.133, and 10988.000 joins only when every computed source is passed, as power.'),
  ('carbon', 'advanced', 'final', null, 12, 'What target does the Agbor path print for 2033, its end year?', '["16830.083 t, the target the curves are checked on", "39270.193 t, 30 percent below the baseline", "31578.593 t, as on the full inventory", "40640.276 t, the 2031 emissions"]'::jsonb, 1, 'The straight line ends at 39270.193 in 2033. 16830.083 is the curves'' target, 30 percent of the total, 31578.593 the end point on the partial inventory, and 40640.276 an emissions figure.'),
  ('carbon', 'advanced', 'final', null, 13, 'On the full Agbor inventory, in which years does the unabated gap column print a positive gap?', '["2027, 2028 and 2033", "2027 and 2033 only", "2028, 2032 and 2033", "2033, the end year alone"]'::jsonb, 0, 'Positive entries: 494.298, 798.595 and 1370.083, in those three years. Every other year of the scheduled path reads 0.000; 2032 shows a gap only once vapour recovery is unscheduled.'),
  ('carbon', 'advanced', 'final', null, 14, 'With Vapour recovery on the storage tanks left unscheduled, what does the path''s abated column read in 2031?', '["15460.000 t, all six live", "7410.000 t, as in 2029", "12060.000 t, one refused", "13610.000 t"]'::jsonb, 3, 'Without its start year the vapour measure never joins, so the column stays where 2030 left it. 15460.000 is the scheduled figure, and 12060.000 the curve total with a refused measure.'),
  ('carbon', 'advanced', 'final', null, 15, 'An over-abatement refusal comes back from the path. What does it tell the user to look for?', '["The start years, for a measure scheduled with no start year", "The baseline, for an inventory line that could not be computed", "The measures, for double counting or a source outside the baseline", "The rate, for a percentage typed where a fraction belongs"]'::jsonb, 2, 'Abating more than the baseline would drive emissions below zero, so the engine points the user at the measures themselves: counted twice, or acting on a source the baseline does not hold.'),
  ('carbon', 'advanced', 'final', null, 16, 'The basisNote for a saving with no basis declared says IPCC default factors are on which basis?', '["Gross calorific value, which is HHV", "Net calorific value, which is LHV", "Net calorific value, which is HHV", "Whichever basis the saving declares"]'::jsonb, 1, 'The basisNote closes: "(IPCC default factors are on net calorific value, which is LHV)." The course''s factor of 56.1 kg CO2e per GJ is SYNTHETIC, and the Agbor saving declares all three quantities on LHV.'),
  ('carbon', 'advanced', 'final', null, 17, 'When priceSaving calls abatementCost for the invented Agbor saving, which figure goes in as the abatement?', '["The energy saving, 11800 GJ", "annualTonnesCo2e, 661.980", "annualValue, 88500.00 USD a year", "The SYNTHETIC factor, 56.1 kg CO2e per GJ"]'::jsonb, 1, 'The hand-over maps tonnes to the abatement slot. Money, 88500.00, fills the savings slot; the gigajoules and the factor are not among the three arguments the digest names.'),
  ('carbon', 'advanced', 'final', null, 18, 'In the direct abatementCost call for the invented saving, over 8 years at 0.1, which pair is the capital recovery factor and the annualised capital?', '["0.26379748 and 4748.35 USD", "0.14676332 and 39363.24 USD", "0.18744402 and 88500.00 USD", "0.18744402 and 39363.24 USD"]'::jsonb, 3, 'An 8 year life at 0.1 gives 0.18744402, which turns 210000 into 39363.24 a year. The other pairs borrow the heater tuning row, the vapour factor or the annual value.'),
  ('carbon', 'advanced', 'final', null, 19, 'Which output of the invented Agbor saving is undiscounted, with no life and no rate in it?', '["simplePaybackYears, 2.372881", "costPerTonneCo2e, -74.2270 USD", "capitalRecoveryFactor, 0.18744402", "annualisedCapital, 39363.24 USD"]'::jsonb, 0, 'The payback divides 210000 by one year''s value and stops there. The other three all pass through the 8 year life and the 0.1 rate.'),
  ('carbon', 'advanced', 'final', null, 20, 'With Purchased power left blank, which total and intensity does energyIntensity print?', '["877000.000 GJ and 707.2581 MJ a tonne", "781000.000 GJ and 707.2581 MJ a tonne", "781000.000 GJ and 629.8387 MJ a tonne", "877000.000 GJ and 629.8387 MJ a tonne"]'::jsonb, 2, 'Dropping the 96000.000 GJ stream leaves 781000.000 and a lower 629.8387, flagged incomplete. The complete pair is 877000.000 with 707.2581.'),
  ('carbon', 'advanced', 'final', null, 21, 'How does the energyIntensity disclaimer frame the peer figure of 680 MJ a tonne?', '["As the Solomon Energy Intensity Index for Agbor", "As a benchmark the engine ships with the module", "As the intensity with a stream missing, a floor", "As one the user supplied and has the right to use"]'::jsonb, 3, 'The disclaimer''s last sentence: the peer figure compared is one you supplied and have the right to use. The Solomon index is named only to say this figure is NOT it, and floor is the peerNote''s word for a missing stream.'),
  ('carbon', 'advanced', 'final', null, 22, 'Which heating value basis does priceSaving return for the invented Agbor saving?', '["LHV, the basis all three quantities declare", "HHV, the basis the factor would need", "None, with the basisNote attached", "LHV for money and HHV for carbon"]'::jsonb, 0, 'SECTION 23: the saving, the fuel price and the factor are all declared on LHV, and the output table reads basis LHV. The basisNote is the no-basis-declared row, and a saving on LHV with a factor on HHV is refused.'),
  ('carbon', 'advanced', 'final', null, 23, 'The flare''s emission is left out and the over-claims column on the 9400 t curve comes back empty. How is that empty column read?', '["The flare''s 9400 t claim fits within what the flare emits.", "The curve found no over-claim, so it gives a verdict on the target.", "The flare''s claim was not checked, and the basis names the flare.", "The flare''s claim was refused and taken off the curve and totals."]'::jsonb, 2, 'SECTION 21: "Where a claim acts on a source whose emission is not passed, it cannot be checked, the verdict is none and the basis names the source." That row prints the basis naming steam, flare, power, vents and a total abatement of 18660.000 t, so the claim stays on the curve.'),
  ('carbon', 'advanced', 'final', null, 24, 'What does SECTION 18 print for Solar for purchased power with the whole capital set against one year?', '["764.5161 USD a tonne, in the one-year column", "823.3333 USD a tonne, in the one-year column", "-13.5714 USD a tonne, at a rate of 0", "45.8573 USD a tonne, at a rate of 0.1"]'::jsonb, 1, 'Of SECTION 18''s two columns, the capital-against-one-year column is the one marked computed here: 823.3333 for Solar and 764.5161 for flare recovery. -13.5714 is Solar''s cost per tonne at a rate of 0 and 45.8573 its cost per tonne at 0.1.'),
  ('carbon', 'advanced', 'final', null, 25, 'On a measure with capital, which box left blank draws the refusal that speaks of setting a one-off capital cost against one year''s saving?', '["The discount rate", "The capital cost", "The annual abatement", "The life"]'::jsonb, 3, 'Only the life refusal speaks of setting a one-off capital cost against one year''s saving. The others speak of straight-line annualisation, of free capital and of a missing abatement.'),
  ('carbon', 'advanced', 'final', null, 26, 'On a measure with capital, which of these boxes, left blank, does abatementCost take as 0 and name in assumedZero?', '["The rate", "The annual cost", "The capital", "The measure''s life"]'::jsonb, 1, 'Running figures are the named zeros; a blank running cost comes back listed in assumedZero. Capital, rate and life, on a measure with capital, are refused when blank.'),
  ('carbon', 'advanced', 'final', null, 27, 'Which discount rate does abatementCost accept on a measure with capital?', '["0.1, typed as a fraction", "10, typed as a percentage", "1, the top of the range", "Blank, to be read as 0"]'::jsonb, 0, 'The accepted range is above -1 and below 1, so 1 itself falls outside it and 10 is refused with the hint 0.1. A blank rate with capital is refused outright.'),
  ('carbon', 'advanced', 'final', null, 28, 'In 2029, the year the Heat integration project joins the path, how many tonnes does the abated column show?', '["4010.000 t", "13610.000 t", "7410.000 t", "5310.000 t"]'::jsonb, 2, 'The 2029 row: 7410.000 abated, 48690.276 emitted. 4010.000 is 2028 and 13610.000 is 2030; 5310.000 is the curve''s pays-for-itself total, a different figure.'),
  ('carbon', 'advanced', 'final', null, 29, 'What does the Agbor path print for abated tonnes and emissions in 2027?', '["760.000 t abated, 54190.276 t emitted", "1910.000 t abated, 53695.978 t emitted", "4010.000 t abated, 52090.276 t emitted", "1910.000 t abated, 54190.276 t emitted"]'::jsonb, 3, 'In 2027 heater tuning and trap repair are live and the abated column reads 1910.000; emissions are the baseline less that. 53695.978 is that year''s target, and the last pair is 2028.'),
  ('carbon', 'advanced', 'final', null, 30, 'With the electricity factor blank, what does the Agbor inventory print?', '["56100.276 tCO2e, reportable false", "45112.276 tCO2e, reportable false", "45112.276 tCO2e, reportable true", "A refusal naming purchased electricity"]'::jsonb, 1, 'The inventory still totals, one line short, and says so: 45112.276 with reportable false and one line that could not be computed.'),
  ('carbon', 'advanced', 'final', null, 31, 'Which set of inputs does SECTION 18 print for Tune the fired heaters?', '["Capital 18000 USD over 3 years, factor 0.40211480", "Capital 45000 USD over 5 years, factor 0.26379748", "Capital 18000 USD over 5 years, factor 0.26379748", "Capital 18000 USD over 5 years, factor 0.13147378"]'::jsonb, 2, 'Heater tuning: 18000 of capital, a 5 year life, 0.26379748. The 3 year life and 45000 of capital belong to trap repair, and 0.13147378 to the two 15 year measures.'),
  ('carbon', 'advanced', 'final', null, 32, 'What annual cost does SECTION 18 print for Vapour recovery on the storage tanks?', '["14000 USD a year", "21000 USD a year", "105000 USD a year", "0 USD a year"]'::jsonb, 0, 'The running cost column: 14000 on the vapour row, 21000 on solar, 105000 on flare recovery and 0 on the three that pay for themselves.'),
  ('carbon', 'advanced', 'final', null, 33, 'Which of these abatementCost calls returns costPerTonne none without refusing?', '["The abatement left blank", "An abatement of -500 t a year", "The capital cost left blank", "An abatement of 0 typed"]'::jsonb, 3, 'The typed zero is the one call of the four that SECTION 19 prints as accepted, and it answers costPerTonne none with paysForItself false. The blank abatement, the -500 t and the blank capital are each refused.'),
  ('carbon', 'advanced', 'final', null, 34, 'The 9400 t curve prints a residual to target of 0.000 t. Which meetsTarget does the same row print?', '["true, as the residual to target is 0.000 t", "true, and labelled an upper bound", "none, beside that residual of 0.000 t", "false, with a residual of 1370.083 t"]'::jsonb, 2, 'SECTION 21 prints meetsTarget none on that row, and says where a claim exceeds what its source emits the curve adds up tonnes that do not exist. The residual of 1370.083 t is the six measures as costed, whose basis names sources with no computed emission.'),
  ('carbon', 'advanced', 'final', null, 35, 'What does SECTION 18 print as the Heat integration project''s cost per tonne at a rate of 0 (straight line)?', '["-14.2492, at 0.1", "-66.6667 USD a tonne", "-120.5882, capital 0 typed", "688.2353 USD, one year"]'::jsonb, 1, 'Straight line, the rate-0 column: -66.6667. The 0.1 column gives -14.2492, capital 0 typed gives -120.5882 (SECTION 19), and 688.2353 sits in the one-year column marked computed here.'),
  ('carbon', 'advanced', 'final', null, 36, 'Which of these does SECTION 25 list as a rule in force for the path?', '["A measure with no start year is named.", "A measure with no start year starts in the baseline year.", "A baseline of zero is accepted from an inventory that computed nothing.", "A year whose measures abate more than the baseline is drawn at zero."]'::jsonb, 0, 'SECTION 25 places three path rules in SECTION 22: a baseline that is not positive is refused, a measure with no start year is named, and a year whose scheduled measures abate more than the baseline is refused. SECTION 22 prints the unscheduled measure left off the path.'),
  ('carbon', 'advanced', 'final', null, 37, 'Name the curve''s costliest step and the year it joins the path.', '["Flare gas recovery, 2031", "Vapour recovery on the storage tanks, 2031", "Solar for purchased power, 2028", "Flare gas recovery, 2030"]'::jsonb, 3, 'Ranked cheapest first, the sixth step is flare recovery at 78.1002 USD a tonne, and its start-year input is 2030. Vapour recovery starts 2031 and Solar 2028.'),
  ('carbon', 'advanced', 'final', null, 38, 'Which year''s target does the Agbor path print as 51291.681 t?', '["2027", "2029", "2028", "2030"]'::jsonb, 2, 'The falling line reads 53695.978 in 2027, 51291.681 in 2028, 48887.383 in 2029 and 46483.086 in 2030.'),
  ('carbon', 'advanced', 'final', null, 39, 'What does energyIntensity return when the throughput is left blank?', '["complete false, at 629.8387 MJ a tonne.", "A refusal: a throughput is required.", "An intensity of 0.000 with versus peer none.", "The total GJ, with the intensity none."]'::jsonb, 1, 'Without the divisor the engine refuses. The 629.8387 figure comes from a blank stream with the throughput present.'),
  ('carbon', 'advanced', 'final', null, 40, 'What share of Agbor''s 877000.000 GJ does Imported steam carry?', '["0.046750", "0.109464", "0.843786", "1.040085"]'::jsonb, 0, 'Imported steam''s 41000.000 GJ is 0.046750 of the total. The other shares are purchased power and fuel gas, and 1.040085 is a ratio to the peer.'),
  ('carbon', 'advanced', 'final', null, 41, '707.2581 MJ a tonne: which arithmetic does SECTION 24 show for it?', '["Total GJ over the peer intensity of 680", "Fuel gas GJ x 1000 over the throughput", "Total GJ x 1000 over 781000.000 GJ", "Total GJ x 1000 over the throughput in tonnes"]'::jsonb, 3, '877000.000 x 1000 / 1240000 = 707.2581, marked computed here and equal to the engine. Dividing by the peer gives the ratio 1.040085, a different output.'),
  ('carbon', 'advanced', 'final', null, 42, 'The Heat integration project: which figure is its net annual cost in SECTION 18?', '["361552.89 USD", "-127251.65 USD", "-48447.11 USD", "484221.51 USD"]'::jsonb, 2, 'Heat integration: annualised capital 361552.89, savings 410000, net -48447.11. -127251.65 is heater tuning and 484221.51 is flare recovery.');
